  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 1, 'Ask an expert: write the question first', 'Before any expert session, spend 15 minutes on one question worth asking.', '[{"t": "text", "text": "Experts answer the question you ask, not the one you meant. Pick a person you could ask this term (a visiting speaker, a teacher, someone in your family) and write **one** question for them."}, {"t": "list", "items": ["Start with what you already know; write that down so the question is not about it.", "Ask about a decision they made, not a fact you could look up.", "Keep it under 20 words. Say it out loud twice."]}, {"t": "key", "q": "Open or closed?", "text": "A closed question can be answered with yes or no. An open question starts with how, why or what, and gets you a story."}, {"t": "check", "q": "Which question would get the best answer?", "a": ["Do you like your job?", "What is the hardest decision you made this year, and why?", "Is science important?", "How old are you?"], "c": 1}]'::jsonb, 15, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Ask an expert: write the question first');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 1, 'Pen pal letter to a partner school', 'Introduce your town, your school and one thing nobody expects, in a letter a stranger would enjoy.', '[{"t": "text", "text": "Write to a student your age at a school in another country. Imagine they know nothing about where you live."}, {"t": "list", "items": ["Paragraph one: where you are and what it looks like out of the window right now.", "Paragraph two: a normal school day, hour by hour.", "Paragraph three: one thing about your town that would surprise them, and one question for them."]}, {"t": "key", "q": "Why ask a question at the end?", "text": "A letter that ends with a question is a conversation. A letter that ends with a full stop is a report."}, {"t": "check", "q": "Which closing line is most likely to get a reply?", "a": ["Bye.", "That is everything about me.", "What does your walk to school look like?", "Write back."], "c": 2}]'::jsonb, 30, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Pen pal letter to a partner school');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 1, 'Check it before you share it', 'Fifteen minutes on the three checks that catch most false posts.', '[{"t": "text", "text": "Pick any surprising post, headline or video you have seen this week. Before you decide whether it is true, run three checks."}, {"t": "list", "items": ["Who made it? Find the account or site, then search for it somewhere else.", "Is it current? Look for the date; old photos get reused for new events.", "What do others say? Open two more sources that are not quoting the first one."]}, {"t": "key", "q": "What is lateral reading?", "text": "Leaving the page to see what the rest of the web says about its source, instead of judging the page by how it looks."}, {"t": "check", "q": "A video has 2 million views. What does that tell you about whether it is true?", "a": ["It must be true", "It must be false", "Nothing on its own", "It is a news report"], "c": 2}]'::jsonb, 15, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Check it before you share it');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 1, 'Careers: interview someone about their job', 'Thirty minutes with anyone who works, and five questions that reveal what the job is really like.', '[{"t": "text", "text": "Choose someone who works, in any job. Ask the five questions below, write down the answers, then write three sentences on whether you would want that job and why."}, {"t": "list", "items": ["What does a good day look like?", "What did you have to learn that nobody warned you about?", "What would you tell someone my age who wanted to do this?", "What do you do when something goes wrong?", "What is the one skill that matters most?"]}, {"t": "key", "q": "Why ask about bad days?", "text": "Job descriptions list the good parts. The bad parts are what decide whether a job suits you."}]'::jsonb, 30, '11plus', true, 5 where not exists (select 1 from public.ed_activity where title = 'Careers: interview someone about their job');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 2, 'Share your world in five frames', 'Tell the story of your neighbourhood in exactly five photographs, in order.', '[{"t": "text", "text": "Five photos, one place, one story. They must work **in order**: the first opens, the last closes."}, {"t": "list", "items": ["Frame 1: the widest view you can find.", "Frames 2 to 4: details a visitor would walk past.", "Frame 5: something that changes every day.", "Give the set a title of three words."]}, {"t": "key", "q": "What is sequencing?", "text": "Choosing the order that creates meaning. The same five photos in a different order tell a different story."}, {"t": "check", "q": "Which should come first?", "a": ["A close-up of a door handle", "The widest view of the street", "A photo of your lunch", "A selfie"], "c": 1}]'::jsonb, 40, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Share your world in five frames');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 2, 'A poster with one word', 'Design a poster that says one word and still makes people stop.', '[{"t": "text", "text": "Choose one word that matters to you this week. Design a poster where it is the only text. Size, colour, placement and texture have to do the talking."}, {"t": "list", "items": ["Try the word huge, then tiny in a corner. Which is louder?", "Use two colours at most.", "Make three versions; keep the one a friend reads from across the room."]}, {"t": "key", "q": "What is visual hierarchy?", "text": "The order your eye reads things in. Designers control it with size, contrast and empty space."}, {"t": "check", "q": "Which makes a word stand out most on a white poster?", "a": ["Grey text, small", "Black text with lots of empty space around it", "Five colours at once", "A busy background"], "c": 1}]'::jsonb, 30, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'A poster with one word');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 2, 'Thirty-second film with no cuts', 'Plan and shoot a single-take film that tells a complete story.', '[{"t": "text", "text": "One shot, no edits, thirty seconds, a beginning and an end. Plan it on paper first: where the camera starts, what it sees, where it finishes."}, {"t": "list", "items": ["Storyboard four moments on sticky notes.", "Rehearse the camera move twice without recording.", "Record three takes; keep the quietest one."]}, {"t": "key", "q": "What is a long take?", "text": "A single continuous shot. With no cuts to hide behind, timing and movement have to be planned like choreography."}]'::jsonb, 45, '11plus', true, 10 where not exists (select 1 from public.ed_activity where title = 'Thirty-second film with no cuts');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 3, 'Plan an expedition day', 'Budget, kit list and risk plan for one day of a trip to somewhere wild.', '[{"t": "text", "text": "You are planning day two of a school expedition to a mountain, a coast or a forest. Produce three things: a timetable, a kit list and a risk plan."}, {"t": "list", "items": ["Timetable: wake-up to lights-out, with walking times you can defend.", "Kit list: everything one person carries, with weights.", "Risk plan: five things that could go wrong and what you would do about each."]}, {"t": "key", "q": "What is a risk assessment?", "text": "A list of what could go wrong, how likely it is, how bad it would be, and what you do to make it less likely or less bad."}, {"t": "check", "q": "Which is the best response to a forecast of heavy rain on a ridge walk?", "a": ["Go anyway", "Choose a lower route and set a turn-back time", "Leave the waterproofs behind", "Walk faster"], "c": 1}]'::jsonb, 45, 'all', true, 10 where not exists (select 1 from public.ed_activity where title = 'Plan an expedition day');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 3, 'Where does your tap water go?', 'Trace a glass of water from your tap to the sea.', '[{"t": "text", "text": "Find out, using maps and your water company''s website, where your drinking water comes from and where the water you flush ends up. Draw the journey as a line with five stops."}, {"t": "key", "q": "What is a catchment?", "text": "The area of land that drains into one river. Everything that happens on that land, farms, roads, towns, ends up in the water."}, {"t": "check", "q": "Water that goes down a sink usually goes to…", "a": ["Straight to the sea", "A treatment works, then a river", "The reservoir", "The ground under the house"], "c": 1}]'::jsonb, 30, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Where does your tap water go?');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 3, 'Sixty-second country', 'Teach the class one country in a minute, using three objects.', '[{"t": "text", "text": "Pick a country none of your friends could place on a map. Find three objects (or pictures of objects) that explain something true about life there. Present them in sixty seconds."}, {"t": "list", "items": ["One object about food or farming.", "One about how people get around.", "One that would surprise everyone."]}, {"t": "key", "q": "Why objects?", "text": "A fact is forgotten by lunchtime. An object people can picture stays."}]'::jsonb, 25, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Sixty-second country');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 4, 'Rehearse like a professional', 'A 25-minute rehearsal routine you can use for any piece: music, dance or drama.', '[{"t": "text", "text": "Pick a piece you are working on. Follow this routine once, properly, and write down what changed."}, {"t": "list", "items": ["Five minutes: warm up the body or the instrument slowly.", "Ten minutes: the hardest eight bars (or eight lines) only, at half speed, five times.", "Five minutes: one full run with no stopping, whatever happens.", "Five minutes: write three notes to yourself for next time."]}, {"t": "key", "q": "What is a note?", "text": "A short, specific instruction a director or teacher gives after a run: ''louder on the entrance'', not ''be better''."}, {"t": "check", "q": "Why practise the hardest part first?", "a": ["It is the most fun", "Your attention is freshest and the rest of the piece benefits", "It is shorter", "It makes the warm-up unnecessary"], "c": 1}]'::jsonb, 25, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Rehearse like a professional');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 4, 'A scene with no words', 'Stage a sixty-second scene that tells a clear story without speech.', '[{"t": "text", "text": "In a pair or a three, act out a complete story, a problem and what happens about it, in sixty seconds with no words. Perform it to someone and ask them what happened."}, {"t": "list", "items": ["Decide the one thing each character wants.", "Plan where everyone stands at the start and the end.", "Use one object."]}, {"t": "key", "q": "What is blocking?", "text": "Where actors stand and move on stage. Good blocking shows relationships before anyone speaks."}]'::jsonb, 30, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'A scene with no words');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 5, 'Build a debate case in twenty minutes', 'Claim, evidence, impact: the shape of an argument that survives a rebuttal.', '[{"t": "text", "text": "Take a motion, for example ''This house would ban homework''. Build the case **for** and the case **against**, each with three arguments."}, {"t": "list", "items": ["Claim: one sentence that could be true or false.", "Evidence: a fact, an example or an expert.", "Impact: why it matters to the people in the room."]}, {"t": "key", "q": "What is a rebuttal?", "text": "Answering the other side''s best argument before making your own. Ignoring it tells the judges you could not."}, {"t": "check", "q": "Which is the strongest claim?", "a": ["Homework is bad", "Homework is boring", "Homework after 7pm reduces sleep, and sleep affects memory", "Everyone hates homework"], "c": 2}]'::jsonb, 30, '11plus', true, 5 where not exists (select 1 from public.ed_activity where title = 'Build a debate case in twenty minutes');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 5, 'Flash fiction: exactly one hundred words', 'A complete story with a turn, in precisely one hundred words.', '[{"t": "text", "text": "Write a story of exactly 100 words. Not 99, not 101. It needs a character, a problem and a moment where something changes."}, {"t": "list", "items": ["Draft long, then cut: adjectives first.", "Make the last sentence change how you read the first.", "Read it aloud; cut anything you stumble on."]}, {"t": "key", "q": "Why the word limit?", "text": "Limits force choices. Every word has to earn its place, which is the whole craft of editing."}]'::jsonb, 25, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Flash fiction: exactly one hundred words');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 5, 'Explain it to a nine-year-old', 'Take a topic from a lesson this week and explain it so a younger child would get it.', '[{"t": "text", "text": "Choose the hardest idea from any lesson this week. Write an explanation a nine-year-old could follow: short words, one example, no jargon."}, {"t": "key", "q": "What does teaching show?", "text": "If you cannot explain it simply, you have not understood it yet. The gaps you find are exactly what to revise."}, {"t": "check", "q": "Which explanation of gravity is best for a nine-year-old?", "a": ["Gravity is a force proportional to mass", "Everything pulls on everything, and the Earth is so big its pull wins, so things fall", "F = Gm1m2/r²", "Gravity is complicated"], "c": 1}]'::jsonb, 20, '11plus', true, 5 where not exists (select 1 from public.ed_activity where title = 'Explain it to a nine-year-old');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 6, 'Pitch a micro-grant project', 'You have fifty pounds and four weeks to improve something for other people. Make the case.', '[{"t": "text", "text": "Write a one-page pitch for a small project that helps people in your school or community. Imagine a panel will fund the best three."}, {"t": "list", "items": ["The problem, in two sentences, with one piece of evidence.", "What you will do, week by week.", "What the fifty pounds buys, line by line.", "How you will know it worked."]}, {"t": "key", "q": "Output or outcome?", "text": "An output is what you did (we ran four sessions). An outcome is what changed because of it (twelve Year 7s now walk to school together)."}, {"t": "check", "q": "Which is an outcome?", "a": ["We printed 200 flyers", "We held a meeting", "Litter on the field halved in a month", "We bought bins"], "c": 2}]'::jsonb, 45, 'all', true, 10 where not exists (select 1 from public.ed_activity where title = 'Pitch a micro-grant project');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 6, 'Lead a five-minute meeting', 'Run a short, real meeting with an agenda and a decision at the end.', '[{"t": "text", "text": "Gather three people for something real: planning a club session, a form trip, a game. Run a five-minute meeting that ends with one decision and who does what."}, {"t": "list", "items": ["Say the one thing the meeting must decide, out loud, at the start.", "Go round once; everyone speaks, nobody speaks twice until all have.", "End by repeating the decision and the names next to each task."]}, {"t": "key", "q": "What is an agenda?", "text": "The list of what a meeting will decide, in order. Without one, meetings become conversations."}]'::jsonb, 20, '11plus', true, 5 where not exists (select 1 from public.ed_activity where title = 'Lead a five-minute meeting');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 6, 'The active bystander', 'What to do when you see something unfair, in four safe steps.', '[{"t": "text", "text": "Think of a time you saw someone being left out, teased or talked over. Most people freeze. This activity gives you four things you can do instead, none of which need you to be brave or loud."}, {"t": "list", "items": ["Distract: start a different conversation or activity.", "Delegate: tell someone who can help, right away.", "Document: remember or note what happened, for later.", "Direct: if it is safe, say one plain sentence, like ''that is not fair''."]}, {"t": "key", "q": "Why do people freeze?", "text": "Everyone assumes someone else will act. The more people watching, the less likely any one of them steps in. Knowing that is half the cure."}, {"t": "check", "q": "A friend is being talked over in a group. Which is the safest first step?", "a": ["Shout at the group", "Ask your friend a direct question so they get the floor", "Walk away", "Record it secretly"], "c": 1}]'::jsonb, 20, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'The active bystander');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 7, 'Ask why five times', 'Take one everyday thing and dig down to first principles.', '[{"t": "text", "text": "Pick an object or a rule: a zip, a traffic light, ''no running in corridors''. Ask **why** it is the way it is. Then ask why about the answer. Five times."}, {"t": "key", "q": "What are first principles?", "text": "The basic facts a thing rests on, once the habits and assumptions are stripped away. Engineers start there when the usual answer stops working."}, {"t": "check", "q": "''Why is the sky blue?'' ''Because of the atmosphere.'' What is the best next question?", "a": ["Is it blue everywhere?", "What does the atmosphere do to sunlight to make it look blue?", "Who said so?", "Is the sea blue too?"], "c": 1}]'::jsonb, 20, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Ask why five times');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 7, 'Design a fair dice roller', 'Write the steps a computer would follow to roll a fair six-sided die, then test it.', '[{"t": "text", "text": "No code needed. Write, in numbered plain-English steps, how a computer could pick a number from 1 to 6 so that every number is equally likely. Then roll a real die 60 times and record the results."}, {"t": "list", "items": ["Step 1 should start from something that is already random.", "Your steps must never produce 0 or 7.", "Compare your 60 rolls with the 10 you would expect of each number."]}, {"t": "key", "q": "What does fair mean here?", "text": "Every outcome has the same chance. Sixty rolls will not give exactly ten of each; a fair die wobbles around ten, a loaded one does not."}, {"t": "check", "q": "Which rule picks 1 to 6 fairly from a random number between 0 and 1?", "a": ["Multiply by 6 and round to the nearest whole number", "Multiply by 6, round down, add 1", "Multiply by 7 and round down", "Add 1 and multiply by 6"], "c": 1}]'::jsonb, 30, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Design a fair dice roller');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 7, 'The two-minute experiment', 'Test one claim about the world with a controlled experiment that fits in two minutes.', '[{"t": "text", "text": "Pick a claim: ''cold water boils faster'', ''the heavier ball drops first'', ''paper planes fly further with the nose folded''. Design a test where only one thing changes."}, {"t": "list", "items": ["Write the prediction before you start.", "Change one thing; keep everything else the same.", "Repeat it three times and use the middle result."]}, {"t": "key", "q": "What is a control?", "text": "The version where you change nothing. Without it you cannot tell whether your change did anything."}]'::jsonb, 30, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'The two-minute experiment');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 8, 'A week of movement', 'Seven days, a daily movement log, and one honest number at the end.', '[{"t": "text", "text": "For seven days, note every ten minutes or more of movement that gets you slightly out of breath: walking to school counts, so does dancing in your room. Total it at the end."}, {"t": "list", "items": ["Aim for sixty minutes a day, in any pieces.", "Mark the days you hit it.", "Pick one day you missed and plan how you would reach it next week."]}, {"t": "key", "q": "Moderate or vigorous?", "text": "Moderate: you can talk but not sing. Vigorous: you can only manage a few words. Both count; vigorous counts double."}, {"t": "check", "q": "Which counts as moderate activity?", "a": ["Scrolling on the sofa", "A brisk walk where talking is easy but singing is not", "Sleeping", "Sitting in assembly"], "c": 1}]'::jsonb, 60, 'all', true, 10 where not exists (select 1 from public.ed_activity where title = 'A week of movement');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 8, 'Money matters: a week on a budget', 'Plan a week''s spending on a fixed amount and see what survives.', '[{"t": "text", "text": "You have £20 for a week: food you buy yourself, travel, anything fun. Plan it in a table before the week, then write down what actually happened."}, {"t": "list", "items": ["Split every item into need or want.", "Keep £2 unplanned; something always comes up.", "At the end, note the one thing you would cut next time."]}, {"t": "key", "q": "Need or want?", "text": "A need is something that goes wrong if you skip it. Most spending is wants, which is fine, as long as you know which is which."}, {"t": "check", "q": "You have £3 left on Thursday. Which is the better choice?", "a": ["Spend it now in case it disappears", "Keep it for the bus on Friday", "Borrow £5 from a friend", "Buy a lottery ticket"], "c": 1}]'::jsonb, 30, '11plus', true, 5 where not exists (select 1 from public.ed_activity where title = 'Money matters: a week on a budget');
  insert into public.ed_activity (cat, title, blurb, blocks, minutes, ages, pub, points) select 8, 'Wellbeing toolkit: the worry plan', 'A ten-minute method for a worry that keeps coming back.', '[{"t": "text", "text": "Write the worry in one sentence. Then split it: the part you can do something about, and the part you cannot. Make a plan for the first part. For the second, decide when you will next think about it, and not before."}, {"t": "key", "q": "What is box breathing?", "text": "Breathe in for four, hold for four, out for four, hold for four. Four rounds. It slows the heart, which tells the brain the emergency is over."}, {"t": "check", "q": "A worry about tomorrow''s test. Which part can you act on?", "a": ["Whether the questions are hard", "Reviewing the two topics you keep getting wrong", "What the teacher thinks", "The weather"], "c": 1}]'::jsonb, 10, 'all', true, 5 where not exists (select 1 from public.ed_activity where title = 'Wellbeing toolkit: the worry plan');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) select 2, 'competition', 'Share your world: five frames', 'Five photographs of where you live, in an order that tells a story. Judged on the story, not the camera.', '[{"t": "text", "text": "Enter the five-frame story from the activity: a link to the five photos in order, their three-word title and **two sentences** on why that order."}, {"t": "key", "q": "Judging", "text": "60% the story the order tells, 40% what the frames notice."}]'::jsonb, now(), now() + interval '21 days', 'all' where not exists (select 1 from public.ed_competition where title = 'Share your world: five frames');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) select 6, 'challenge', 'Entrepreneurs'' challenge: the ten-pound idea', 'Turn ten pounds into something people want. Pitch, plan and prove it.', '[{"t": "text", "text": "Imagine you are given £10 to start something that could pay it back within a month: a service, a product, a one-off event. Enter a one-page plan and, if you ran it, what happened."}, {"t": "list", "items": ["What you sell, to whom, for how much.", "Every cost, down to the pennies.", "The first three customers and how you reach them."]}, {"t": "key", "q": "Judging", "text": "Realism first: a plan that could actually happen beats a bigger idea that could not."}]'::jsonb, now(), now() + interval '30 days', '11plus' where not exists (select 1 from public.ed_competition where title = 'Entrepreneurs'' challenge: the ten-pound idea');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) select 7, 'tournament', 'Chess ladder: autumn', 'Challenge anyone one place above you. Win, and you swap. Standings are posted every Friday.', '[{"t": "text", "text": "Sign up by entering with a sentence about how often you can play. Games are at lunchtime chess club or online with a shared link; report results to the club lead the same day."}, {"t": "key", "q": "How a ladder works", "text": "You can only challenge the one or two players directly above you, so every game matters and nobody waits for a round."}]'::jsonb, now(), now() + interval '45 days', 'all' where not exists (select 1 from public.ed_competition where title = 'Chess ladder: autumn');
  insert into public.ed_competition (cat, kind, title, blurb, blocks, opens, closes, ages) select 5, 'tournament', 'Debate cup: this house believes', 'Pairs, four rounds, motions announced a week ahead. Judges score argument, rebuttal and manners.', '[{"t": "text", "text": "Enter as a pair with your partner''s name in the entry. Round one motions are posted in News. Build your cases with the twenty-minute debate activity."}, {"t": "key", "q": "Scoring", "text": "Argument 40%, rebuttal 40%, delivery 20%. Interrupting costs points."}]'::jsonb, now(), now() + interval '40 days', '11plus' where not exists (select 1 from public.ed_competition where title = 'Debate cup: this house believes');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) select 7, 'Chess club', 'Learn, play and climb the ladder. Boards and clocks provided; beginners welcome.', 'Tuesday', '12:30', 'Library', 16, 'all' where not exists (select 1 from public.ed_club where title = 'Chess club');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) select 1, 'Pen pals & connection hub', 'Write to partner-school students abroad and host the replies. Letters go out once a month.', 'Wednesday', '12:30', 'Room 4', 24, 'all' where not exists (select 1 from public.ed_club where title = 'Pen pals & connection hub');
  insert into public.ed_club (cat, title, blurb, day, time, place, capacity, ages) select 6, 'Young entrepreneurs', 'Plan small ventures, run them at school events and keep the books.', 'Thursday', '15:45', 'Business room', 18, '11plus' where not exists (select 1 from public.ed_club where title = 'Young entrepreneurs');
